const state = { route: location.hash.slice(1) || 'dashboard', input: '', file: null, project: null, clipTitle: '제주도 학생의 미친 삼행시 수준', saved: false, history: [], future: [], captionStyle: { fontSize: 28, color: '#ffffff' }, burnCaptions: true, assetId: null, layers: [], segments: [], segmentStart: null };
