let activeToast = null; let toastTimer = null;
function resetProject() { state.input = ''; state.file = null; state.project = null; state.clipTitle = '제주도 학생의 미친 삼행시 수준'; state.layers = []; state.segments = []; state.segmentStart = null; clips.splice(0, clips.length); }
