function toast(message) { if (!activeToast || !document.body.contains(activeToast)) { activeToast = document.createElement('div'); activeToast.className = 'toast'; document.body.append(activeToast); } activeToast.textContent = message; if (toastTimer) clearTimeout(toastTimer); toastTimer = setTimeout(() => { activeToast?.remove(); activeToast = null; toastTimer = null; }, 2400); }
function escapeHtml(value) { return String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;').replaceAll("'", '&#039;'); }
